const EMPTY = { CAT: {}, providers: [], byId: {} }
const ROWS = [
  ['Pricing from', (p) => p.price, null],
  ['Settlement', (p) => p.settle, null],
  ['Countries', (p) => String(p.countries), (p) => p.countries],
  ['Currencies', (p) => (p.currencies ? String(p.currencies) : '—'), (p) => p.currencies],
  ['Licence', (p) => p.licence, null],
  ['API', (p) => p.apiText, (p) => p.api.length],
  ['Uptime, 90 days', (p) => p.uptime.toFixed(2) + '%', (p) => p.uptime],
  ['Typical go-live', (p) => p.golive + ' days', (p) => -p.golive],
  ['Relay score', (p) => p.score + ' / 100', (p) => p.score],
]
class Component extends DCLogic {
  state = {
    ids: this.props.ids?.length ? this.props.ids.slice(0, 4) : ['meridian', 'cobalt', 'pacifica'],
    diff: false,
    picker: false,
    q: '',
    pcat: 'all',
    requested: {},
    save: false,
    saveName: '',
    saveCat: null,
    activeSaved: this.props.savedId ?? null,
  }
  componentDidMount() {
    if (!RELAY)
      this._i = setInterval(() => {
        if (RELAY) {
          clearInterval(this._i)
          this.forceUpdate()
        }
      }, 40)
  }
  componentWillUnmount() {
    clearInterval(this._i)
  }
  componentDidUpdate(prev) {
    if (prev.ids !== this.props.ids && this.props.ids?.length)
      this.setState({ ids: this.props.ids.slice(0, 4), activeSaved: this.props.savedId ?? null })
  }
  renderVals() {
    const R = RELAY ?? EMPTY,
      S = this.state
    const picked = S.ids.map((id) => R.byId[id]).filter(Boolean)
    const canAdd = picked.length < 4
    const cols = `200px repeat(${picked.length}, minmax(0,1fr))${canAdd ? ' minmax(0,1fr)' : ''}`
    let rows = ROWS.map(([label, fmt, score]) => {
      const vals = picked.map(fmt)
      const top = score && picked.length > 1 ? Math.max(...picked.map(score)) : null
      const bc = top == null ? 0 : picked.filter((p) => score(p) === top).length
      return {
        label,
        same: new Set(vals).size <= 1,
        cells: picked.map((p, i) => {
          const best = top != null && bc < picked.length && score(p) === top
          return { v: vals[i], best, fg: best ? '#f7f8f8' : '#b4b8bf', weight: best ? 500 : 400 }
        }),
      }
    })
    if (S.diff) rows = rows.filter((r) => !r.same)
    const q = S.q.trim().toLowerCase()
    const options = R.providers
      .filter(
        (p) =>
          !S.ids.includes(p.id) &&
          (S.pcat === 'all' || p.kind === S.pcat) &&
          (!q || (p.name + ' ' + p.hq).toLowerCase().includes(q)),
      )
      .slice(0, 40)
      .map((p) => ({ ...p, add: () => this.setState((s) => ({ ids: [...s.ids, p.id], picker: false, q: '' })) }))
    const catChip = (k, label, cur, set) => ({
      kind: k,
      label,
      pick: () => set(k),
      bg: cur === k ? 'rgba(255,255,255,.08)' : 'transparent',
      fg: cur === k ? '#f7f8f8' : '#8a8f98',
      ring: cur === k ? 'inset 0 0 0 1px rgba(255,255,255,.14)' : 'inset 0 0 0 1px rgba(255,255,255,.06)',
    })
    const cats = Object.entries(R.CAT)
    const on = S.picker,
      sOn = S.save,
      has = picked.length > 0,
      nameOk = S.saveName.trim().length > 0
    const saved = this.props.saved ?? []
    const act = saved.find((s) => s.id === S.activeSaved)
    return {
      heading: act ? act.name : 'Compare Providers',
      cols,
      rows,
      canAdd,
      hasCols: has,
      noCols: !has,
      actOp: has ? 1 : 0.4,
      countLabel: picked.length + ' of 4 selected',
      picked: picked.map((p) => {
        const r = S.requested[p.id]
        return {
          ...p,
          remove: () => this.setState((s) => ({ ids: s.ids.filter((x) => x !== p.id) })),
          request: () => this.setState((s) => ({ requested: { ...s.requested, [p.id]: true } })),
          btnLabel: r ? 'Intro requested' : 'Request intro',
          btnFg: r ? '#6fe3b4' : '#0f1011',
          btnBg: r ? 'rgba(111,227,180,.1)' : '#f7f8f8',
        }
      }),
      options,
      noOptions: options.length === 0,
      q: S.q,
      onQ: (e) => this.setState({ q: e.target.value }),
      pickCats: [
        catChip('all', 'All', S.pcat, (k) => this.setState({ pcat: k })),
        ...cats.map(([k, v]) => catChip(k, v.label, S.pcat, (k2) => this.setState({ pcat: k2 }))),
      ],
      togglePicker: () => this.setState((s) => ({ picker: !s.picker })),
      pick: {
        op: on ? 1 : 0,
        tf: on ? 'translateY(0) scale(1)' : 'translateY(-4px) scale(.98)',
        pe: on ? 'auto' : 'none',
      },
      toggleDiff: () => this.setState((s) => ({ diff: !s.diff })),
      diffTrack: S.diff ? '#6fe3b4' : 'rgba(255,255,255,.14)',
      diffKnob: S.diff ? 'translateX(12px)' : 'translateX(0)',
      clearAll: () => this.setState({ ids: [], picker: false, activeSaved: null }),
      suggest: () => this.setState({ ids: ['meridian', 'cobalt', 'pacifica'] }),
      addToShortlist: () => has && this.props.onAddToShortlist?.(S.ids),
      openSave: () =>
        has &&
        this.setState({
          save: true,
          saveName: act?.name ?? '',
          saveCat: act?.kind && act.kind !== 'all' ? act.kind : null,
        }),
      closeSave: () => this.setState({ save: false }),
      sm: {
        op: sOn ? 1 : 0,
        pe: sOn ? 'auto' : 'none',
        tf: sOn ? 'translate(-50%,-50%) scale(1)' : 'translate(-50%,-48%) scale(.98)',
      },
      saveName: S.saveName,
      onSaveName: (e) => this.setState({ saveName: e.target.value }),
      saveCats: [
        catChip('none', 'None', S.saveCat ?? 'none', () => this.setState({ saveCat: null })),
        ...cats.map(([k, v]) => catChip(k, v.label, S.saveCat, (k2) => this.setState({ saveCat: k2 }))),
      ].map((c) => (c.kind === 'none' ? { ...c, kind: 'all' } : c)),
      saveSummary: picked.map((p) => p.name).join(', '),
      saveBtn: { fg: nameOk ? '#0f1011' : '#62666d', bg: nameOk ? '#f7f8f8' : 'rgba(255,255,255,.05)' },
      doSave: () => {
        if (!nameOk) return
        const id = act && act.name === S.saveName.trim() ? act.id : 'cmp' + Date.now()
        this.props.onSaveCompare?.({ id, name: S.saveName.trim(), kind: S.saveCat ?? 'all', ids: S.ids })
        this.setState({ save: false, activeSaved: id })
      },
      savedCount: saved.length || '',
      hasSaved: saved.length > 0,
      noSaved: saved.length === 0,
      saved: saved.map((s) => ({
        ...s,
        meta: (s.kind !== 'all' ? R.CAT[s.kind]?.label + ' · ' : '') + s.ids.length + ' Providers',
        names: s.ids
          .map((i) => R.byId[i]?.name)
          .filter(Boolean)
          .join(', '),
        bg: s.id === S.activeSaved ? 'rgba(255,255,255,.035)' : 'rgba(255,255,255,.012)',
        ring: s.id === S.activeSaved ? '0 0 0 1px rgba(255,255,255,.14)' : '0 0 0 1px rgba(255,255,255,.06)',
        open: () => this.setState({ ids: s.ids.slice(0, 4), activeSaved: s.id }),
        del: (e) => {
          e.stopPropagation()
          this.props.onDeleteCompare?.(s.id)
          if (S.activeSaved === s.id) this.setState({ activeSaved: null })
        },
      })),
    }
  }
}

